import time
secret = b'secret'
def check(guess):
    for i in range(len(secret)):
        if guess[i] != secret[i]:
            return i  # number of matching chars
        time.sleep(0.1)  # artificial delay to amplify
    return len(secret)

# Attacker can guess each byte by finding which gives the highest return value.
